alter table public.caleris_season_yearbooks add column if not exists member_id uuid references public.members(id) on delete cascade;
update public.caleris_season_yearbooks y set member_id=p.member_id from public.profiles p where y.generated_by=p.user_id and y.member_id is null;
alter table public.caleris_season_yearbooks alter column member_id set not null;
alter table public.caleris_season_yearbooks drop constraint if exists caleris_season_yearbooks_season_id_key;
alter table public.caleris_season_yearbooks add constraint caleris_season_yearbooks_member_season_key unique(member_id,season_id);
drop policy if exists "cp yearbook read" on public.caleris_season_yearbooks;
create policy "cp yearbook owner read" on public.caleris_season_yearbooks for select to authenticated using(member_id=public.caleris_current_member_id() or exists(select 1 from public.site_admins where user_id=auth.uid()));
create or replace function public.caleris_save_yearbook(p_season uuid,p_title text,p_content jsonb) returns void language plpgsql security definer set search_path=public as $$declare m uuid:=public.caleris_current_member_id();begin if m is null then raise exception 'member_profile_required';end if;insert into public.caleris_season_yearbooks(season_id,member_id,title,content,status,generated_by) values(p_season,m,left(p_title,160),p_content,'draft',auth.uid()) on conflict(member_id,season_id) do update set title=excluded.title,content=excluded.content,status='draft',generated_at=now(),generated_by=auth.uid();end$$;
create or replace function public.caleris_xp_level(p_total numeric) returns integer language plpgsql immutable as $$declare l integer:=0;t numeric:=50;begin while l<100 and p_total>=t loop l:=l+1;t:=t*2;end loop;return l;end$$;
create or replace function public.caleris_set_xp_reward(p_source text,p_reward integer) returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'not_authorized';end if;if p_reward<0 or p_reward>100000 then raise exception 'invalid_reward';end if;update public.caleris_xp_reward_settings set reward_xp=p_reward,updated_by=auth.uid(),updated_at=now() where source_type=p_source;if not found then raise exception 'invalid_source';end if;end$$;
grant execute on function public.caleris_set_xp_reward(text,integer) to authenticated;
